   TestRunner.True(!authority.MatchesManualDerivedPlan(source,Chunk7ManualDerivedSelection.ManualOutputLeaf,Chunk7ManualDerivedSelection.ManualOutputName,true),"Owner seed borrowed Manual 2.");
