   TestRunner.True(!authority.MatchesManualDerivedPlan(source,Chunk7ManualDerivedSelection.OwnerSeedOutputLeaf,Chunk7ManualDerivedSelection.ManualOutputName,true),"Owner seed borrowed bootstrap name.");
